import React, { useState, useEffect } from 'react';
import axios from 'axios';

const App = () => {
  const [jobs, setJobs] = useState([]);
  const [jobForm, setJobForm] = useState({
    title: '',
    company: '',
    location: '',
    description: '',
    link: '',
    logo_url: '',
    company_link: '',
    country: '',
    posted_on: '',
    is_featured: false
  });

  // Fetch jobs from the API
  const fetchJobs = async () => {
    try {
      const response = await axios.get('http://localhost:5000/jobs');
      setJobs(response.data);
    } catch (error) {
      console.error('Error fetching jobs', error);
    }
  };

  // Handle form input change
  const handleChange = (e) => {
    const { name, value } = e.target;
    setJobForm({ ...jobForm, [name]: value });
  };

  // Add a job
  const addJob = async (e) => {
    e.preventDefault();
    try {
      await axios.post('http://localhost:5000/jobs', jobForm);
      fetchJobs(); // Refresh the job listings
      // Clear the form after submitting
      setJobForm({
        title: '',
        company: '',
        location: '',
        description: '',
        link: '',
        logo_url: '',
        company_link: '',
        country: '',
        posted_on: '',
        is_featured: false
      });
    } catch (error) {
      console.error('Error adding job', error);
    }
  };

  // Delete a job
  const deleteJob = async (id) => {
    try {
      await axios.delete(`http://localhost:5000/jobs/${id}`);
      fetchJobs(); // Refresh the job listings
    } catch (error) {
      console.error('Error deleting job', error);
    }
  };

  useEffect(() => {
    fetchJobs();
  }, []);

  return (
    <div>
      <h1>Job Listings</h1>

      <form onSubmit={addJob}>
        <input
          type="text"
          name="title"
          placeholder="Job Title"
          value={jobForm.title}
          onChange={handleChange}
        />
        <input
          type="text"
          name="company"
          placeholder="Company"
          value={jobForm.company}
          onChange={handleChange}
        />
        <input
          type="text"
          name="location"
          placeholder="Location"
          value={jobForm.location}
          onChange={handleChange}
        />
        <textarea
          name="description"
          placeholder="Job Description"
          value={jobForm.description}
          onChange={handleChange}
        />
        <input
          type="text"
          name="link"
          placeholder="Job Link"
          value={jobForm.link}
          onChange={handleChange}
        />
        <input
          type="text"
          name="logo_url"
          placeholder="Company Logo URL"
          value={jobForm.logo_url}
          onChange={handleChange}
        />
        <input
          type="text"
          name="company_link"
          placeholder="Company Link"
          value={jobForm.company_link}
          onChange={handleChange}
        />
        <input
          type="text"
          name="country"
          placeholder="Country"
          value={jobForm.country}
          onChange={handleChange}
        />
        <input
          type="text"
          name="posted_on"
          placeholder="Posted On"
          value={jobForm.posted_on}
          onChange={handleChange}
        />
        <label>
          Featured:
          <input
            type="checkbox"
            name="is_featured"
            checked={jobForm.is_featured}
            onChange={(e) => setJobForm({ ...jobForm, is_featured: e.target.checked })}
          />
        </label>
        <button type="submit">Add Job</button>
      </form>

      <div>
        {jobs.map((job) => (
          <div key={job.id}>
            <h3>{job.title}</h3>
            <p>{job.company} - {job.location}</p>
            <p>{job.description}</p>
            {job.logo_url && <img src={job.logo_url} alt="Company Logo" width="50" />}
            <p><strong>Country:</strong> {job.country}</p>
            <p><strong>Posted On:</strong> {job.posted_on}</p>
            {job.is_featured && <p><strong>Featured Job</strong></p>}
            <a href={job.link} target="_blank" rel="noopener noreferrer">View Job</a>
            <button onClick={() => deleteJob(job.id)}>Delete</button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;
